"use client";

import { useState } from "react";
import CollectionsPane from "./CollectionsPane";
import { handleImportCurl } from "./importCurl";
import * as buildCurl  from "./buildCurl";
import * as util from "../components/util";

export default function ApiPlaygroundPage() {
    const [method, setMethod] = useState("GET");
    const [url, setUrl] = useState("");
    const [paramsRows, setParamsRows] = useState([]);
    const [headerRows, setHeaderRows] = useState([
        { enabled: true, key: "Content-Type", value: "application/json", description: "" },
    ]);
    const [bodyInput, setBodyInput] = useState("{}");
    const [activeTab, setActiveTab] = useState("Params");
    const [importCurlText, setImportCurlText] = useState("");
    const [importMessage, setImportMessage] = useState("");
    const [copyMessage, setCopyMessage] = useState("");
    const [showSuccessToast, setShowSuccessToast] = useState(false);
    const canSendBody = method !== "GET" && method !== "DELETE";

    const updateRow = (setter, rowIndex, field, fieldValue) => {
        setter((prev) => prev.map((row, index) => (index === rowIndex ? { ...row, [field]: fieldValue } : row)));
    };

    const addRow = (setter) => {
        setter((prev) => [...prev, util.createEmptyRow()]);
    };

    const removeRow = (setter, rowIndex) => {
        setter((prev) => prev.filter((_, index) => index !== rowIndex));
    };

    const { requestUrlPreview } = buildCurl.buildRequestUrlPreview({ paramsRows, url });

    const { curlCommand } = buildCurl.buildCurlParts({
        headerRows,
        canSendBody,
        bodyInput,
        method,
        requestUrlPreview,
    });

    const responsePreview = `{"message": "Response will appear here after you connect request execution."}`;

    const onImportCurlClick = () => {
        handleImportCurl({
            importCurlText,
            setUrl,
            setParamsRows,
            setHeaderRows,
            setBodyInput,
            setMethod,
            setImportCurlText,
            setImportMessage,
            setShowSuccessToast,
            setActiveTab,
        });
    };

    const onCopyCurlClick = () => {
        buildCurl.onCopyCurlClick({ curlCommand, setCopyMessage });
    }

    return (
        <main
            style={{
                height: "100vh",
                boxSizing: "border-box",
                paddingTop: "28px",
                paddingRight: "28px",
                paddingBottom: "28px",
                paddingLeft: "28px",
                color: "#23272f",
                fontFamily: util.APP_FONT,
                overflow: "hidden",
            }}
        >
            {showSuccessToast && (
                <div
                    style={{
                        position: "fixed",
                        top: 18,
                        right: 20,
                        zIndex: 1200,
                        background: "#e8f8ee",
                        border: "1px solid #9fd3b2",
                        color: "#135c32",
                        borderRadius: 10,
                        padding: "10px 12px",
                        fontSize: 13,
                        fontWeight: 700,
                        boxShadow: "0 12px 28px rgba(15, 23, 42, 0.16)",
                    }}
                >
                    Imported cURL successfully.
                </div>
            )}

            <div
                style={{
                    display: "flex",
                    alignItems: "stretch",
                    gap: 14,
                    height: "100%",
                    overflowX: "hidden",
                    overflowY: "hidden",
                }}
            >
                <CollectionsPane />

                <section
                    style={{
                        flex: 1,
                        minWidth: 0,
                        height: "100%",
                        display: "flex",
                        flexDirection: "column",
                        background: "#ffffff",
                        border: "1px solid #dbe5f1",
                        borderRadius: 12,
                        paddingTop: "10px",
                        paddingRight: "20px",
                        paddingBottom: "20px",
                        paddingLeft: "20px",
                        boxShadow: "0 8px 24px rgba(15, 23, 42, 0.06)",
                        overflow: "hidden",
                    }}
                >

                    <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
                        <select
                            value={method}
                            onChange={(e) => setMethod(e.target.value)}
                            style={{
                                border: "1px solid #c7d3e7",
                                borderRadius: 8,
                                padding: "10px",
                                fontWeight: 700,
                                color: "#0b4f6c",
                                background: "#f7fbff",
                            }}
                        >
                            {util.HTTP_METHODS.map((httpMethod) => (
                                <option key={httpMethod} value={httpMethod}>
                                    {httpMethod}
                                </option>
                            ))}
                        </select>

                        <input
                            value={url}
                            onChange={(e) => setUrl(e.target.value)}
                            placeholder="Enter request URL"
                            style={{
                                flex: 1,
                                border: "1px solid #c7d3e7",
                                borderRadius: 8,
                                padding: "10px 12px",
                                fontSize: 14,
                            }}
                        />

                    </div>

                    <div style={{ marginTop: 8, fontSize: 12, color: "#607089" }}>
                        Request URL: {requestUrlPreview}
                    </div>

                    <div style={{ marginTop: 12, display: "flex", gap: 8, borderBottom: "1px solid #dbe5f1", paddingBottom: 8 }}>
                        {util.REQUEST_TABS.map((tab) => {
                            const isActive = activeTab === tab;

                            return (
                                <button
                                    key={tab}
                                    type="button"
                                    onClick={() => setActiveTab(tab)}
                                    style={{
                                        border: isActive ? "1px solid #b9e1ef" : "1px solid #dbe5f1",
                                        background: isActive ? "#eaf7fc" : "#f8fafc",
                                        color: isActive ? "#0b4f6c" : "#44516b",
                                        borderRadius: 8,
                                        padding: "8px 12px",
                                        fontWeight: 700,
                                        cursor: "pointer",
                                    }}
                                >
                                    {tab}
                                </button>
                            );
                        })}
                    </div>

                    {activeTab === "Params" && (
                        <div style={{ marginTop: 12 }}>
                            <div
                                style={{
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    overflow: "hidden",
                                    background: "#fff",
                                    fontSize: 12,
                                }}
                            >
                                <div style={{ display: "grid", gridTemplateColumns: util.TABLE_COLUMNS, background: "#f7fbff", fontWeight: 700, color: "#44516b" }}>
                                    <div style={{ padding: "8px" }}>On</div>
                                    <div style={{ padding: "8px" }}>Key</div>
                                    <div style={{ padding: "8px" }}>Value</div>
                                    <div style={{ padding: "8px" }}>Description</div>
                                    <div style={{ padding: "8px" }} />
                                </div>

                                <div style={{ maxHeight: "20vh", overflowY: "auto" }}>
                                    {paramsRows.map((row, rowIndex) => (
                                        <div key={`param-${rowIndex}`} style={{ display: "grid", gridTemplateColumns: util.TABLE_COLUMNS, borderTop: "1px solid #edf2f8" }}>
                                            <div style={{ padding: "8px" }}>
                                                <input
                                                    type="checkbox"
                                                    checked={row.enabled}
                                                    onChange={(e) => updateRow(setParamsRows, rowIndex, "enabled", e.target.checked)}
                                                />
                                            </div>
                                            <input
                                                value={row.key}
                                                onChange={(e) => updateRow(setParamsRows, rowIndex, "key", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <input
                                                value={row.value}
                                                onChange={(e) => updateRow(setParamsRows, rowIndex, "value", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <input
                                                value={row.description}
                                                onChange={(e) => updateRow(setParamsRows, rowIndex, "description", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <button
                                                type="button"
                                                onClick={() => removeRow(setParamsRows, rowIndex)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", background: "transparent", color: "#b91c1c", cursor: "pointer" }}
                                            >
                                                x
                                            </button>
                                        </div>
                                    ))}
                                </div>

                                <button
                                    type="button"
                                    onClick={() => addRow(setParamsRows)}
                                    style={{ width: "100%", border: "none", borderTop: "1px solid #edf2f8", background: "#f9fbfe", padding: "8px", cursor: "pointer", fontWeight: 600, color: "#0b4f6c" }}
                                >
                                    + Add Param
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "Headers" && (
                        <div style={{ marginTop: 12 }}>
                            <div
                                style={{
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    overflow: "hidden",
                                    background: "#fff",
                                    fontSize: 12,
                                }}
                            >
                                <div style={{ display: "grid", gridTemplateColumns: util.TABLE_COLUMNS, background: "#f7fbff", fontWeight: 700, color: "#44516b" }}>
                                    <div style={{ padding: "8px" }}>On</div>
                                    <div style={{ padding: "8px" }}>Key</div>
                                    <div style={{ padding: "8px" }}>Value</div>
                                    <div style={{ padding: "8px" }}>Description</div>
                                    <div style={{ padding: "8px" }} />
                                </div>

                                <div style={{ maxHeight: "20vh", overflowY: "auto" }}>
                                    {headerRows.map((row, rowIndex) => (
                                        <div key={`header-${rowIndex}`} style={{ display: "grid", gridTemplateColumns: util.TABLE_COLUMNS, borderTop: "1px solid #edf2f8" }}>
                                            <div style={{ padding: "8px" }}>
                                                <input
                                                    type="checkbox"
                                                    checked={row.enabled}
                                                    onChange={(e) => updateRow(setHeaderRows, rowIndex, "enabled", e.target.checked)}
                                                />
                                            </div>
                                            <input
                                                value={row.key}
                                                onChange={(e) => updateRow(setHeaderRows, rowIndex, "key", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <input
                                                value={row.value}
                                                onChange={(e) => updateRow(setHeaderRows, rowIndex, "value", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <input
                                                value={row.description}
                                                onChange={(e) => updateRow(setHeaderRows, rowIndex, "description", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <button
                                                type="button"
                                                onClick={() => removeRow(setHeaderRows, rowIndex)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", background: "transparent", color: "#b91c1c", cursor: "pointer" }}
                                            >
                                                x
                                            </button>
                                        </div>
                                    ))}
                                </div>

                                <button
                                    type="button"
                                    onClick={() => addRow(setHeaderRows)}
                                    style={{ width: "100%", border: "none", borderTop: "1px solid #edf2f8", background: "#f9fbfe", padding: "8px", cursor: "pointer", fontWeight: 600, color: "#0b4f6c" }}
                                >
                                    + Add Header
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "Body" && (
                        <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 12 }}>
                            <textarea
                                value={bodyInput}
                                onChange={(e) => setBodyInput(e.target.value)}
                                onBlur={() => setBodyInput((prev) => util.formatJsonIfPossible(prev))}
                                disabled={!canSendBody}
                                style={{
                                    width: "100%",
                                    minHeight: 260,
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    padding: "10px 12px",
                                    boxSizing: "border-box",
                                    fontSize: 12,
                                    resize: "vertical",
                                    background: canSendBody ? "#fff" : "#f3f5f9",
                                }}
                            />
                        </div>
                    )}

                    {activeTab === "cURL" && (
                        <div style={{ marginTop: 12 }}>
                            <div style={{ position: "relative" }}>
                                <button
                                    type="button"
                                    onClick={onCopyCurlClick}
                                    style={{
                                        position: "absolute",
                                        top: 10,
                                        right: 10,
                                        zIndex: 2,
                                        border: "1px solid #c7d3e7",
                                        background: "#c7d3e7",
                                        borderRadius: 8,
                                        padding: "6px",
                                        lineHeight: 0,
                                        cursor: "pointer",
                                    }}
                                    aria-label="Copy cURL"
                                    title="Copy cURL"
                                >
                                    <img src="/assets/copy.svg" alt="" width="16" height="16" aria-hidden="true" />
                                </button>
                                {copyMessage && (
                                    <span
                                        style={{
                                            position: "absolute",
                                            top: 46,
                                            right: 10,
                                            zIndex: 2,
                                            fontSize: 11,
                                            color: "#52627f",
                                            background: "#c7d3e7",
                                            border: "1px solid #dbe5f1",
                                            borderRadius: 6,
                                            padding: "2px 6px",
                                        }}
                                    >
                                        {copyMessage}
                                    </span>
                                )}

                            <textarea
                                value={curlCommand}
                                readOnly
                                style={{
                                    width: "100%",
                                    minHeight: 260,
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    padding: "10px 12px",
                                    boxSizing: "border-box",
                                    fontSize: 12,
                                    background: "#f8fafc",
                                }}
                            />
                            </div>
                        </div>
                    )}

                    {activeTab === "Import cURL" && (
                        <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 10 }}>
                            <textarea
                                value={importCurlText}
                                onChange={(e) => setImportCurlText(e.target.value)}
                                placeholder="Paste cURL here..."
                                style={{
                                    width: "100%",
                                    minHeight: 260,
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    padding: "10px 12px",
                                    boxSizing: "border-box",
                                    fontSize: 12,
                                    background: "#fff",
                                }}
                            />

                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                                <button
                                    type="button"
                                    onClick={onImportCurlClick}
                                    style={{
                                        border: "1px solid #0b4f6c",
                                        background: "#0b4f6c",
                                        color: "#fff",
                                        borderRadius: 8,
                                        padding: "10px 12px",
                                        fontWeight: 700,
                                        cursor: "pointer",
                                    }}
                                >
                                    Import to Request
                                </button>

                                <span style={{ fontSize: 12, color: "#52627f" }}>{importMessage}</span>
                            </div>
                        </div>
                    )}

                    <div style={{ marginTop: 12 }}>
                        <div style={{ marginBottom: 6, fontSize: 12, fontWeight: 700, color: "#30415f" }}>Response</div>
                        <textarea
                            value={responsePreview}
                            readOnly
                            style={{
                                width: "100%",
                                minHeight: 180,
                                border: "1px solid #d7e1ef",
                                borderRadius: 8,
                                padding: "10px 12px",
                                boxSizing: "border-box",
                                fontSize: 12,
                                background: "#ffffff",
                                color: "#2a3447",
                                resize: "vertical",
                            }}
                        />
                    </div>
                </section>
            </div>
        </main>
    );
}
