"use client";

import { useCallback, useEffect, useRef, useState } from "react";

const DEFAULT_COLLECTIONS = ["Authentication", "Orders", "Reservations"];
const PANEL_WIDTH = {
  initial: 360,
  min: 240,
  preferredMin: 320,
  max: 720,
  contentReserve: 220,
  gap: 14,
};

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export default function CollectionsPane() {
  const [collections, setCollections] = useState(DEFAULT_COLLECTIONS);
  const [newCollection, setNewCollection] = useState("");
  const [pendingDeleteIndex, setPendingDeleteIndex] = useState(null);
  const [panelWidth, setPanelWidth] = useState(PANEL_WIDTH.initial);
  const [isResizingPanel, setIsResizingPanel] = useState(false);
  const panelRef = useRef(null);

  const startPanelResize = useCallback((e) => {
    e.preventDefault();
    setIsResizingPanel(true);
    document.body.style.cursor = "col-resize";
    document.body.style.userSelect = "none";
  }, []);

  const stopPanelResize = useCallback(() => {
    setIsResizingPanel(false);
    document.body.style.cursor = "";
    document.body.style.userSelect = "";
  }, []);

  const handlePanelResize = useCallback((e) => {
    if (!isResizingPanel || !panelRef.current) return;

    const panelRect = panelRef.current.getBoundingClientRect();
    const containerWidth = panelRef.current.parentElement?.clientWidth ?? 960;
    const maxWidth = Math.min(
      PANEL_WIDTH.max,
      Math.max(
        PANEL_WIDTH.preferredMin,
        containerWidth - PANEL_WIDTH.contentReserve - PANEL_WIDTH.gap
      )
    );
    const minWidth = Math.min(PANEL_WIDTH.min, maxWidth);
    const nextWidth = clamp(e.clientX - panelRect.left, minWidth, maxWidth);

    setPanelWidth(nextWidth);
  }, [isResizingPanel]);

  useEffect(() => {
    if (!isResizingPanel) return undefined;

    window.addEventListener("mousemove", handlePanelResize);
    window.addEventListener("mouseup", stopPanelResize);

    return () => {
      window.removeEventListener("mousemove", handlePanelResize);
      window.removeEventListener("mouseup", stopPanelResize);
    };
  }, [handlePanelResize, isResizingPanel, stopPanelResize]);

  const addCollection = () => {
    const name = newCollection.trim();
    if (!name) return;
    setCollections((prev) => [...prev, name]);
    setNewCollection("");
  };

  const removeCollection = (rowIndex) => {
    setCollections((prev) => prev.filter((_, index) => index !== rowIndex));
    setPendingDeleteIndex(null);
  };

  return (
    <aside
      ref={panelRef}
      style={{
        width: `${panelWidth}px`,
        maxWidth: `calc(100% - ${PANEL_WIDTH.gap}px)`,
        height: "100%",
        display: "flex",
        flexDirection: "column",
        minHeight: 0,
        background: "linear-gradient(180deg, #f8fafc 0%, #eef3f8 100%)",
        border: "1px solid #d7e0ea",
        borderRadius: 12,
        paddingTop: "18px",
        paddingRight: "16px",
        paddingBottom: "16px",
        paddingLeft: "16px",
        boxShadow: "6px 0 20px rgba(15, 23, 42, 0.08)",
        position: "relative",
        transition: isResizingPanel ? "none" : "width 0.12s ease",
        overflow: "hidden",
      }}
    >
      <h2 style={{ margin: 0, fontSize: 20, color: "#10203a" }}>Collections</h2>

      <div style={{ display: "flex", flexWrap: "wrap", gap: 10, marginTop: 12 }}>
        <input
          type="text"
          value={newCollection}
          onChange={(e) => setNewCollection(e.target.value)}
          placeholder="New collection name"
          style={{
            flex: "1 1 160px",
            border: "1px solid #c7d3e7",
            borderRadius: 8,
            paddingTop: "10px",
            paddingRight: "12px",
            paddingBottom: "10px",
            paddingLeft: "12px",
            fontSize: 14,
          }}
        />
        <button
          type="button"
          onClick={addCollection}
          style={{
            border: "1px solid #0b4f6c",
            background: "#0b4f6c",
            color: "#fff",
            borderRadius: 8,
            paddingTop: "10px",
            paddingRight: "12px",
            paddingBottom: "10px",
            paddingLeft: "12px",
            fontWeight: 600,
            cursor: "pointer",
            whiteSpace: "nowrap",
          }}
        >
          Add
        </button>
      </div>

      <div
        style={{
          marginTop: 14,
          flex: 1,
          minHeight: 0,
          overflowY: "auto",
          paddingRight: 4,
          paddingBottom: 10,
          scrollPaddingBottom: 12,
        }}
      >
        <ul style={{ marginTop: 0, marginBottom: 0, paddingLeft: 0, color: "#1f2a44", listStyle: "none" }}>
          {collections.map((collection, index) => (
            <li
              key={`${collection}-${index}`}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                marginTop: 6,
                marginBottom: index === collections.length - 1 ? 6 : 0,
                border: "1px solid #dbe5f1",
                background: "#ffffff",
                borderRadius: 10,
                paddingTop: "10px",
                paddingRight: "12px",
                paddingBottom: "10px",
                paddingLeft: "12px",
                fontWeight: 600,
              }}
            >
              <span>{collection}</span>
              <button
                type="button"
                onClick={() => setPendingDeleteIndex(index)}
                aria-label={`Delete ${collection}`}
                style={{
                  marginLeft: "auto",
                  background: "transparent",
                  border: "none",
                  cursor: "pointer",
                  padding: 0,
                }}
              >
                <img src="/assets/trash.svg" alt="" width="16" height="16" aria-hidden="true" />
              </button>
            </li>
          ))}
        </ul>
      </div>

      {pendingDeleteIndex !== null && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            zIndex: 1400,
            background: "rgba(15, 23, 42, 0.35)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              width: "min(420px, calc(100vw - 32px))",
              background: "#ffffff",
              border: "1px solid #d7e0ea",
              borderRadius: 12,
              paddingTop: 16,
              paddingRight: 16,
              paddingBottom: 14,
              paddingLeft: 16,
              boxShadow: "0 18px 42px rgba(15, 23, 42, 0.24)",
            }}
          >
            <div style={{ fontWeight: 700, color: "#10203a" }}>Delete Collection?</div>
            <div style={{ marginTop: 8, fontSize: 13, color: "#334155" }}>
              Are you sure you want to delete
              {" "}
              <strong>{collections[pendingDeleteIndex]}</strong>
              ?. This action cannot be undone.
            </div>
            <div style={{ marginTop: 14, display: "flex", justifyContent: "flex-end", gap: 8 }}>
              <button
                type="button"
                onClick={() => setPendingDeleteIndex(null)}
                style={{
                  border: "1px solid #c7d3e7",
                  background: "#ffffff",
                  color: "#334155",
                  borderRadius: 8,
                  padding: "8px 12px",
                  fontWeight: 600,
                  cursor: "pointer",
                }}
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => removeCollection(pendingDeleteIndex)}
                style={{
                  border: "1px solid #b91c1c",
                  background: "#b91c1c",
                  color: "#ffffff",
                  borderRadius: 8,
                  padding: "8px 12px",
                  fontWeight: 700,
                  cursor: "pointer",
                }}
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}

      <div
        onMouseDown={startPanelResize}
        title="Drag to resize"
        style={{
          position: "absolute",
          top: 0,
          right: 0,
          width: 10,
          height: "100%",
          borderTopRightRadius: 12,
          borderBottomRightRadius: 12,
          cursor: "col-resize",
          background: isResizingPanel
            ? "rgba(11, 79, 108, 0.22)"
            : "rgba(11, 79, 108, 0.12)",
        }}
      />
    </aside>
  );
}